'use strict';

/**
* Compute the squared hinge loss.
*
* @module @stdlib/ml/base/loss/float64/squared-hinge
*
* @example
* var squaredHinge = require( '@stdlib/ml/base/loss/float64/squared-hinge' );
*
* var v = squaredHinge( 1.0, 1.0, 0.782 );
* // returns ~0.0475
*
* v = squaredHinge( 1.0, 1.0, 0.202 );
* // returns ~0.6368
*
* v = squaredHinge( 1.0, 1.0, -0.999 );
* // returns ~3.996
*
* v = squaredHinge( 1.0, -1.0, 0.2 );
* // returns 1.44
*
* v = squaredHinge( 1.0, -1.0, -1.5 );
* // returns 0.0
*/

// MODULES //

var main = require( './main.js' );


// EXPORTS //

module.exports = main;
